      "name": "Sweet Sangria",
      "country": "",
      "source": "TheCocktailDB",
      "sourceUrl": "https://www.thecocktaildb.com/drink/13024",
      "ingredients": [
        "2 bottles Red wine",
        "1 cup Sugar",
        "2 cups hot Water",
        "1 cup Apple",
        "wedges Orange",
        "wedges Lime",
        "Lemon",
        "Fresca"
      ],
      "instructions": [
        {
          "@type": "HowToStep",
          "text": "Dissolve the sugar in hot water and cool. Peel the citrus fruits and break into wedges. Mix the wine, sugar syrup, fruit, and Fresca in a pitcher and put in the fridge for a few hours. Serve in tall glasses with a straw."
        }
      ],
