      "idMeal": "53555",
      "strMeal": "Classic Potato Salad",
      "strMealAlternate": null,
      "strCategory": "Side",
      "strArea": null,
      "strCountry": "Denmark",
      "strInstructions": "Boil potatoes in lightly salted water for 10 to 12 minutes. Drain water when a potato speared with a fork and lifted out of the water easily glides off the fork and falls back into the pot. Let potatoes stand and cool.\r\nBreak off and discard the stringy ends of the asparagus spears, then chop into small pieces. You can pour boiling water over the chopped asparagus and let it soak for 2 minutes if you prefer a less raw taste.\r\nFinely chop chives, red onion and radish.\r\nStir the dressing ingredients together and season with salt and pepper.\r\nReserve some of the chives for garnish and combine the rest of the vegetables with the dressing.\r\nSeason with salt and pepper, garnish with chives and serve as a side dish.\r\nTip\r\nWhen in season, you can add fresh peas to this potato salad",
