      "strCountry": "Estonia",
      "strInstructions": "Pour the beans into the sieve, remove liquid.\r\nGrate carrots and add beans, Mix and mash together. Season with garlic, thyme, salt and pepper.\r\nForm the dough into round buns, dip them slightly into the bread crumbs, and press the fritters.\r\nFry fritters in hot oil for a short time until the fritters are browned.  Place on the greased or /baking paper-lined oven plate and bake at 200C for 10 minutes.",
