      "strArea": null,
      "strCountry": "Cayman Islands",
      "strInstructions": "Peel and cut potatoes in cubes, boil in salted water until tender. Chop peppers and onion and set aside. Mix together mayonnaise, mustard, sugar and black pepper and set aside. Drain potatoes once tender and place in large mixing bowl. Add remaining ingredients and mix well. The salad may be served warm, but is normally served after it has been refrigerated for 2 to 3 hours.",
